//! Naive date/time handling with chrono compatible parsing behaviour.
//!
//! `chrono` produces error messages like "input is out of range",
//! "input contains invalid characters", "premature end of input" and
//! "trailing input".  Those strings are needed verbatim, so the parser is
//! re-implemented here with the same semantics.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ParseErrorKind {
    OutOfRange,
    NotEnough,
    Invalid,
    TooShort,
    TooLong,
    BadFormat,
}

impl ParseErrorKind {
    pub fn message(&self) -> &'static str {
        match self {
            ParseErrorKind::OutOfRange => "input is out of range",
            ParseErrorKind::NotEnough => "input is not enough for unique date and time",
            ParseErrorKind::Invalid => "input contains invalid characters",
            ParseErrorKind::TooShort => "premature end of input",
            ParseErrorKind::TooLong => "trailing input",
            ParseErrorKind::BadFormat => "bad or unsupported format string",
        }
    }
}

/// Date in the proleptic Gregorian calendar.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct NaiveDate {
    pub year: i32,
    pub month: u32,
    pub day: u32,
}

fn is_leap(year: i32) -> bool {
    (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

pub fn days_in_month(year: i32, month: u32) -> u32 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if is_leap(year) {
                29
            } else {
                28
            }
        }
        _ => 0,
    }
}

const CUMULATIVE_DAYS: [i64; 12] = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];

impl NaiveDate {
    pub fn from_ymd_opt(year: i32, month: u32, day: u32) -> Option<NaiveDate> {
        if !(1..=12).contains(&month) {
            return None;
        }
        if day < 1 || day > days_in_month(year, month) {
            return None;
        }
        Some(NaiveDate { year, month, day })
    }

    /// Days since 1970-01-01 (may be negative).
    pub fn num_days_from_epoch(&self) -> i64 {
        // days from civil 0000-03-01 based algorithm
        let y = self.year as i64;
        let m = self.month as i64;
        let d = self.day as i64;
        let y_adj = if m <= 2 { y - 1 } else { y };
        let era = if y_adj >= 0 { y_adj } else { y_adj - 399 } / 400;
        let yoe = y_adj - era * 400; // [0, 399]
        let mp = (m + 9) % 12; // March = 0
        let doy = (153 * mp + 2) / 5 + d - 1; // [0, 365]
        let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
        era * 146097 + doe - 719468
    }

    pub fn from_days_since_epoch(z: i64) -> NaiveDate {
        let z = z + 719468;
        let era = if z >= 0 { z } else { z - 146096 } / 146097;
        let doe = z - era * 146097;
        let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
        let y = yoe + era * 400;
        let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
        let mp = (5 * doy + 2) / 153;
        let d = doy - (153 * mp + 2) / 5 + 1;
        let m = if mp < 10 { mp + 3 } else { mp - 9 };
        NaiveDate {
            year: (y + if m <= 2 { 1 } else { 0 }) as i32,
            month: m as u32,
            day: d as u32,
        }
    }

    /// 0 = Monday .. 6 = Sunday
    pub fn weekday(&self) -> u32 {
        // 1970-01-01 was a Thursday (index 3 with Monday = 0)
        let d = self.num_days_from_epoch();
        ((d + 3).rem_euclid(7)) as u32
    }

    pub fn succ_days(&self, n: i64) -> NaiveDate {
        NaiveDate::from_days_since_epoch(self.num_days_from_epoch() + n)
    }

    pub fn pred_days(&self, n: i64) -> NaiveDate {
        NaiveDate::from_days_since_epoch(self.num_days_from_epoch() - n)
    }

    pub fn first_day_of_month(&self) -> NaiveDate {
        NaiveDate {
            year: self.year,
            month: self.month,
            day: 1,
        }
    }

    /// Monday of the current ISO week.
    pub fn first_day_of_week(&self) -> NaiveDate {
        self.pred_days(self.weekday() as i64)
    }

    pub fn first_day_of_year(&self) -> NaiveDate {
        NaiveDate {
            year: self.year,
            month: 1,
            day: 1,
        }
    }

    pub fn format(&self) -> String {
        format!("{:04}-{:02}-{:02}", self.year, self.month, self.day)
    }
}

/// Time of day stored as seconds since midnight.  A `leap` flag marks a
/// ":60" second which chrono keeps as leap second (and which is *not*
/// normalised away).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct NaiveTime {
    pub secs: u32,
    pub leap: bool,
}

impl NaiveTime {
    pub fn from_hms(hour: u32, minute: u32, second: u32) -> Option<NaiveTime> {
        if hour >= 24 || minute >= 60 || second >= 60 {
            return None;
        }
        Some(NaiveTime {
            secs: hour * 3600 + minute * 60 + second,
            leap: false,
        })
    }

    pub fn hour(&self) -> u32 {
        if self.leap {
            (self.secs - 60) / 3600
        } else {
            self.secs / 3600
        }
    }

    pub fn minute(&self) -> u32 {
        if self.leap {
            ((self.secs - 60) % 3600) / 60
        } else {
            (self.secs % 3600) / 60
        }
    }

    pub fn second(&self) -> u32 {
        if self.leap {
            60
        } else {
            self.secs % 60
        }
    }

    pub fn format_hm(&self) -> String {
        format!("{:02}:{:02}", self.hour(), self.minute())
    }
}

/// A timestamp: date plus seconds of that day (0..=86400).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct NaiveDateTime {
    pub date: NaiveDate,
    pub secs: u32,
}

impl NaiveDateTime {
    pub fn from_parts(date: NaiveDate, hour: u32, minute: u32, second: u32) -> Option<NaiveDateTime> {
        let t = NaiveTime::from_hms(hour, minute, second)?;
        Some(NaiveDateTime {
            date,
            secs: t.secs,
        })
    }

    pub fn time(&self) -> NaiveTime {
        NaiveTime {
            secs: self.secs,
            leap: false,
        }
    }

    pub fn total_secs(&self) -> i64 {
        self.date.num_days_from_epoch() * 86400 + self.secs as i64
    }

    pub fn from_total_secs(total: i64) -> NaiveDateTime {
        let date = NaiveDate::from_days_since_epoch(total.div_euclid(86400));
        let secs = total.rem_euclid(86400) as u32;
        NaiveDateTime { date, secs }
    }

    /// Difference in whole minutes, rounded to the nearest minute.
    pub fn diff_minutes(&self, other: &NaiveDateTime) -> i64 {
        let diff = other.total_secs() - self.total_secs();
        let mins = diff / 60;
        let rem = diff.rem_euclid(60);
        if rem >= 30 {
            mins + 1
        } else {
            mins
        }
    }

    pub fn format_full(&self) -> String {
        format!("{} {}", self.date.format(), self.time().format_hm())
    }
}

/// Rounding of a parsed timestamp down to minute precision (as the original
/// binary only supports minute resolution).
pub fn truncate_to_minute(dt: NaiveDateTime) -> NaiveDateTime {
    NaiveDateTime {
        date: dt.date,
        secs: (dt.secs / 60) * 60,
    }
}

pub fn round_to_minute(dt: NaiveDateTime) -> NaiveDateTime {
    let rem = dt.secs % 60;
    if rem < 30 {
        NaiveDateTime {
            date: dt.date,
            secs: dt.secs - rem,
        }
    } else {
        let total = dt.date.num_days_from_epoch() * 86400 + dt.secs as i64 + (60 - rem) as i64;
        NaiveDateTime::from_total_secs(total)
    }
}

// ---------------------------------------------------------------------------
// parsing
// ---------------------------------------------------------------------------

fn skip_ws(s: &str) -> &str {
    s.trim_start_matches(|c: char| c.is_whitespace())
}

/// Parse a number with at least one and at most `max` digits.  Returns the
/// remaining input and the parsed value.
fn scan_number(s: &str, max: usize) -> Result<(&str, i64), ParseErrorKind> {
    let s = skip_ws(s);
    if s.is_empty() {
        return Err(ParseErrorKind::TooShort);
    }
    let mut end = 0;
    for (i, c) in s.char_indices() {
        if c.is_ascii_digit() {
            end = i + c.len_utf8();
            if end - 0 >= max {
                break;
            }
        } else {
            break;
        }
    }
    if end == 0 {
        return Err(ParseErrorKind::Invalid);
    }
    let val: i64 = s[..end].parse().unwrap();
    Ok((&s[end..], val))
}

/// Like `scan_number` but accepts a leading sign.
fn scan_signed_number(s: &str, max: usize) -> Result<(&str, i64), ParseErrorKind> {
    let s = skip_ws(s);
    if s.is_empty() {
        return Err(ParseErrorKind::TooShort);
    }
    let (neg, rest) = if let Some(st) = s.strip_prefix('-') {
        (true, st)
    } else if let Some(st) = s.strip_prefix('+') {
        (false, st)
    } else {
        (false, s)
    };
    let (rest, val) = scan_number(rest, max)?;
    Ok((rest, if neg { -val } else { val }))
}

fn take_literal(s: &str, lit: &str) -> Result<&str, ParseErrorKind> {
    if s.is_empty() {
        return Err(ParseErrorKind::TooShort);
    }
    if !s.starts_with(lit) {
        return Err(ParseErrorKind::Invalid);
    }
    Ok(&s[lit.len()..])
}

/// `%Y-%m-%d`
pub fn parse_date(s: &str) -> Result<NaiveDate, ParseErrorKind> {
    let (rest, year) = scan_signed_number(s, 4)?;
    let rest = take_literal(rest, "-")?;
    let (rest, month) = scan_number(rest, 2)?;
    let rest = take_literal(rest, "-")?;
    let (rest, day) = scan_number(rest, 2)?;
    if !skip_ws(rest).is_empty() {
        return Err(ParseErrorKind::TooLong);
    }
    NaiveDate::from_ymd_opt(year as i32, month as u32, day as u32).ok_or(ParseErrorKind::OutOfRange)
}

/// `%H:%M`
pub fn parse_time(s: &str) -> Result<NaiveTime, ParseErrorKind> {
    let (rest, hour) = scan_number(s, 2)?;
    let rest = take_literal(rest, ":")?;
    let (rest, minute) = scan_number(rest, 2)?;
    if !skip_ws(rest).is_empty() {
        return Err(ParseErrorKind::TooLong);
    }
    if hour >= 24 || minute >= 60 {
        return Err(ParseErrorKind::OutOfRange);
    }
    Ok(NaiveTime {
        secs: (hour as u32) * 3600 + (minute as u32) * 60,
        leap: false,
    })
}

/// `%Y-%m-%d %H:%M`
pub fn parse_datetime_minute(s: &str) -> Result<NaiveDateTime, ParseErrorKind> {
    let (rest, year) = scan_signed_number(s, 4)?;
    let rest = take_literal(rest, "-")?;
    let (rest, month) = scan_number(rest, 2)?;
    let rest = take_literal(rest, "-")?;
    let (rest, day) = scan_number(rest, 2)?;
    let rest = take_literal(rest, " ")?;
