fn pad(s: &str, width: usize) -> String {
    let mut out = s.to_string();
    let len = s.chars().count();
    for _ in len..width {
        out.push(' ');
    }
    out
}

/// Greedy word wrapping, breaking on spaces.
fn wrap(text: &str, avail: usize) -> Vec<String> {
    let mut lines = Vec::new();
    let mut cur = String::new();
    for word in text.split(' ') {
        if cur.is_empty() {
            cur.push_str(word);
        } else if cur.chars().count() + 1 + word.chars().count() <= avail {
            cur.push(' ');
            cur.push_str(word);
        } else {
            lines.push(cur.clone());
            cur.clear();
            cur.push_str(word);
        }
    }
    if !cur.is_empty() || lines.is_empty() {
        lines.push(cur);
    }
    lines
}

fn help_line(indent: usize, spec: &str, col: usize, help: &str) -> String {
    // spec already contains the leading TAB indent
    let mut out = spec.to_string();
    let len = spec.chars().count();
    for _ in len..col {
        out.push(' ');
    }
    let avail = TERM_WIDTH.saturating_sub(col + 4);
    if col + help.chars().count() + 4 >= TERM_WIDTH {
        let lines = wrap(help, avail);
        let mut first = true;
        for l in lines {
            if !first {
                out.push('\n');
                out.push_str(&" ".repeat(col));
            }
            out.push_str(&l);
            first = false;
        }
    } else {
        out.push_str(help);
    }
    out
}

