pub fn render_top_help(bin: &str) -> String {
    let mut out = String::new();
    out.push_str(&format!("{} {}\n", APP_NAME, VERSION));
    out.push_str(AUTHOR);
    out.push('\n');
    out.push_str(ABOUT);
    out.push_str("\n\nUSAGE:\n    ");
    out.push_str(&top_usage(bin));
    out.push_str("\n\nFLAGS:\n");
    let flags: Vec<&ArgSpec> = vec![
        &ArgSpec { id: "help", short: Some('h'), long: Some("help"), kind: ArgKind::Flag, val_name: "", help: "Prints help information", env: None, default: None },
        &ArgSpec { id: "version", short: Some('V'), long: Some("version"), kind: ArgKind::Flag, val_name: "", help: "Prints version information", env: None, default: None },
    ];
    let longest = flags.iter().map(|f| f.spec().chars().count()).max().unwrap_or(2);
    let col = longest + 12;
    for f in flags {
        let spec = format!("    {}", f.rendered());
        out.push_str(&help_line(4, &spec, col, f.help));
        out.push('\n');
    }
    out.push_str("\nOPTIONS:\n");
    let file_env = std::env::var("BARTIB_FILE").unwrap_or_default();
    let f = ArgSpec {
        id: "file",
        short: Some('f'),
        long: None,
        kind: ArgKind::Opt,
        val_name: "FILE",
        help: "the file in which bartib tracks all the activities",
        env: Some("BARTIB_FILE"),
        default: None,
    };
    let opts = vec![&f];
    let longest = opts.iter().map(|o| o.spec().chars().count()).max().unwrap_or(2);
    let col = longest + 12;
    for o in opts {
        let spec = format!("    {}", o.rendered());
        let mut help = o.help.to_string();
        if let Some(env) = o.env {
            help.push_str(&format!(" [env: {}={}]", env, file_env));
        }
        out.push_str(&help_line(4, &spec, col, &help));
        out.push('\n');
    }
    out.push_str("\nSUBCOMMANDS:\n");
    let subs = subcommands();
    let longest = subs.iter().map(|s| s.name.chars().count()).max().unwrap_or(2);
    let col = longest + 8;
    for s in &subs {
        let spec = format!("    {}", s.name);
        out.push_str(&help_line(4, &spec, col, s.about));
        out.push('\n');
    }
    out.push_str("\nTo get help for a specific subcommand, run `bartib [SUBCOMMAND] --help`.\n");
    out.push_str("To get started, view the `start` help with `bartib start --help`\n");
    out
}

pub fn render_sub_help(bin: &str, sub: &SubDef) -> String {
