        for f in sub.flags {
            let spec = format!("    {}", f.rendered());
            out.push_str(&help_line(4, &spec, col, f.help));
            out.push('\n');
        }
    }
    if !sub.opts.is_empty() {
        out.push_str("\nOPTIONS:\n");
        let longest = sub.opts.iter().map(|o| o.spec().chars().count()).max().unwrap_or(2);
        let col = longest + 12;
