            }
            if let Some(d) = o.default {
                help.push_str(&format!(" [default: {}]", d));
            }
            out.push_str(&help_line(4, &spec, col, &help));
            out.push('\n');
        }
    }
    if !sub.positionals.is_empty() {
        out.push_str("\nARGS:\n");
        let longest = sub.positionals.iter().map(|p| p.spec().chars().count()).max().unwrap_or(2);
        let col = longest + 8;
        for p in sub.positionals {
            let spec = format!("    {}", p.spec());
            let mut help = p.help.to_string();
            if let Some(d) = p.default {
                help.push_str(&format!(" [default: {}]", d));
            }
            out.push_str(&help_line(4, &spec, col, &help));
            out.push('\n');
        }
    }
    out
}

// ---------------------------------------------------------------------------
// parsing
// ---------------------------------------------------------------------------

#[derive(Debug)]
pub enum Action {
    Help(String),
    Version,
    Run(&'static str, Matches),
    Err(String),
}

pub struct Matches {
    flags: HashMap<String, bool>,
    values: HashMap<String, Option<String>>,
    positionals: HashMap<String, Vec<String>>,
}

impl Matches {
    pub fn flag(&self, id: &str) -> bool {
        *self.flags.get(id).unwrap_or(&false)
    }
    pub fn value(&self, id: &str) -> Option<&str> {
        self.values.get(id).and_then(|v| v.as_deref())
    }
    pub fn positional(&self, id: &str) -> Option<&str> {
        self.positionals.get(id).and_then(|v| v.first().map(|s| s.as_str()))
    }
    pub fn positionals(&self, id: &str) -> Vec<String> {
        self.positionals.get(id).cloned().unwrap_or_default()
    }
}

fn find_spec<'a>(defs: &'a [ArgSpec], id: &str) -> &'a ArgSpec {
    defs.iter().find(|d| d.id == id).unwrap()
}

fn find_by_long<'a>(defs: &'a [ArgSpec], long: &str) -> Option<&'a ArgSpec> {
    defs.iter().find(|d| d.long == Some(long))
}

fn find_by_short<'a>(defs: &'a [ArgSpec], short: char) -> Option<&'a ArgSpec> {
    defs.iter().find(|d| d.short == Some(short))
}

struct Builder<'a> {
    bin: &'a str,
    sub: &'a SubDef,
    flags: Vec<(&'static ArgSpec, usize)>,
    values: Vec<(&'static ArgSpec, Option<String>)>,
    positionals: Vec<String>,
}

impl<'a> Builder<'a> {
    fn present_usage(&self) -> String {
        let mut items: Vec<String> = Vec::new();
        for (spec, _) in &self.values {
            items.push(spec.usage_repr());
        }
        for (spec, _) in &self.flags {
            items.push(spec.usage_repr());
        }
        items.sort();
        let mut out = format!("{} {}", self.bin, self.sub.name);
        for i in items {
            out.push(' ');
            out.push_str(&i);
        }
        out
    }

    fn err_unknown(&self, arg: &str) -> Action {
        Action::Err(format!(
            "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
            arg,
            sub_usage(self.bin, self.sub)
        ))
    }

    fn err_empty_value(&self, spec: &ArgSpec) -> Action {
        Action::Err(format!(
            "error: The argument '{}' requires a value but none was supplied\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
            spec.usage_repr(),
            self.present_usage()
        ))
    }

    fn err_multiple(&self, spec: &ArgSpec) -> Action {
        Action::Err(format!(
            "error: The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
            spec.usage_repr(),
            self.present_usage()
        ))
    }

    fn err_conflict(&self, a: &ArgSpec, b: &ArgSpec) -> Action {
        Action::Err(format!(
            "error: The argument '{}' cannot be used with '{}'\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
            a.usage_repr(),
            b.usage_repr(),
            self.present_usage()
        ))
    }

    fn err_missing_required(&self, missing: Vec<&ArgSpec>) -> Action {
        let mut list = String::new();
        for m in &missing {
            list.push_str("    ");
            list.push_str(&m.usage_repr());
            list.push('\n');
        }
        Action::Err(format!(
            "error: The following required arguments were not provided:\n{}\nUSAGE:\n    {}\n\nFor more information try --help\n",
            list,
            sub_usage(self.bin, self.sub)
        ))
    }

    fn already_seen(&self, id: &str) -> bool {
        self.flags.iter().any(|(s, _)| s.id == id) || self.values.iter().any(|(s, _)| s.id == id)
    }
}

/// Mutually exclusive argument groups (list/report date selection flags).
fn conflicts_of(id: &str) -> Vec<&'static str> {
    match id {
        "from" => vec!["date", "today", "yesterday", "current_week", "last_week"],
        "to" => vec!["date", "today", "yesterday", "current_week", "last_week"],
        "date" => vec!["today", "yesterday", "current_week", "last_week"],
        "today" => vec!["date", "yesterday", "current_week", "last_week"],
        "yesterday" => vec!["current_week", "last_week"],
        "current_week" => vec!["last_week"],
        "last_week" => vec![],
        _ => vec![],
    }
}

fn conflict_priority(id: &str) -> usize {
    match id {
        "from" => 6,
        "to" => 5,
        "date" => 4,
        "today" => 3,
        "yesterday" => 2,
        "current_week" => 1,
        "last_week" => 0,
        _ => 100,
    }
}

pub fn parse_sub(bin: &str, sub: &SubDef, args: &[String]) -> Action {
    let mut b = Builder {
        bin,
        sub,
        flags: Vec::new(),
        values: Vec::new(),
        positionals: Vec::new(),
    };
    let mut i = 0;
    let mut only_positionals = false;
    let mut pending_opt: Option<&'static ArgSpec> = None;

    while i < args.len() {
        let arg = &args[i];
        i += 1;
        if let Some(spec) = pending_opt.take() {
            b.values.push((spec, Some(arg.clone())));
            continue;
        }
        if only_positionals {
            b.positionals.push(arg.clone());
            continue;
        }
        if arg == "--" {
            only_positionals = true;
            continue;
        }
        if arg.starts_with("--") {
            let body = &arg[2..];
            let (name, inline_val) = match body.find('=') {
                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                None => (body, None),
            };
            match find_by_long(sub.opts, name).or_else(|| find_by_long(sub.flags, name)) {
                Some(spec) => {
                    if spec.kind == ArgKind::Flag {
                        if inline_val.is_some() {
                            return b.err_unknown(&format!("--{}", name));
                        }
                        if b.already_seen(spec.id) {
                            return b.err_multiple(spec);
                        }
                        b.flags.push((spec, 0));
                    } else {
                        if b.already_seen(spec.id) {
                            return b.err_multiple(spec);
                        }
                        match inline_val {
                            Some(v) => b.values.push((spec, Some(v))),
                            None => {
                                if i < args.len() && !args[i].starts_with('-') {
                                    b.values.push((spec, Some(args[i].clone())));
                                    i += 1;
                                } else {
                                    b.values.push((spec, None));
                                    // trailing missing value -> error
                                    return b.err_empty_value(spec);
                                }
                            }
                        }
                    }
                }
                None => return b.err_unknown(&format!("--{}", name)),
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            // short argument(s)
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut ci = 0;
            while ci < chars.len() {
                let c = chars[ci];
                ci += 1;
                let spec = match find_by_short(sub.opts, c).or_else(|| find_by_short(sub.flags, c)) {
                    Some(s) => s,
                    None => return b.err_unknown(&format!("-{}", c)),
                };
                if spec.kind == ArgKind::Flag {
                    if b.already_seen(spec.id) {
                        return b.err_multiple(spec);
                    }
                    b.flags.push((spec, 0));
                } else {
                    if b.already_seen(spec.id) {
                        return b.err_multiple(spec);
                    }
                    let rest: String = chars[ci..].iter().collect();
                    ci = chars.len();
                    if !rest.is_empty() {
                        let val = if let Some(st) = rest.strip_prefix('=') {
                            st.to_string()
                        } else {
                            rest
                        };
                        b.values.push((spec, Some(val)));
                    } else if i < args.len() && !args[i].starts_with('-') {
                        b.values.push((spec, Some(args[i].clone())));
                        i += 1;
                    } else {
                        b.values.push((spec, None));
                        return b.err_empty_value(spec);
                    }
                }
            }
        } else {
            // positional
            if sub.positionals.is_empty() {
                return b.err_unknown(arg);
            }
            let max = if sub.positionals.iter().any(|p| p.many) {
                usize::MAX
            } else {
                sub.positionals.len()
            };
            if b.positionals.len() >= max {
                return b.err_unknown(arg);
            }
            b.positionals.push(arg.clone());
        }
    }

    // conflicts
    let present: Vec<&'static ArgSpec> = b
        .flags
        .iter()
        .chain(b.values.iter())
        .map(|(s, _)| *s)
        .collect();
    let mut present_ids: Vec<&str> = present.iter().map(|s| s.id).collect();
    present_ids.retain(|id| conflicts_of(id).is_some_and(|c| !c.is_empty()));
    if !present_ids.is_empty() {
        present_ids.sort_by_key(|id| std::cmp::Reverse(conflict_priority(id)));
        let a_id = present_ids[0];
        let a = find_spec(sub.flags, a_id)
            .or_else(|| find_spec(sub.opts, a_id))
            .unwrap();
        // conflicting partners present: the last one on the command line
        let partners: Vec<&'static str> = conflicts_of(a_id)
            .into_iter()
            .filter(|p| present.iter().any(|s| s.id == *p))
            .collect();
        if let Some(p_id) = partners
            .iter()
            .max_by_key(|p| b.positional_index_of(p).unwrap_or(0))
            .copied()
        {
            let b_spec = find_spec(sub.flags, p_id)
                .or_else(|| find_spec(sub.opts, p_id))
                .unwrap();
            return b.err_conflict(a, b_spec);
        }
    }

    // required arguments
    let missing: Vec<&ArgSpec> = sub
        .opts
        .iter()
        .filter(|o| matches!(o.id, "description" | "project") && sub.name == "start")
        .filter(|o| !b.values.iter().any(|(s, _)| s.id == o.id))
        .collect();
    if !missing.is_empty() {
        return b.err_missing_required(missing);
    }

    // fill defaults
    let mut flags: HashMap<String, bool> = HashMap::new();
    for (spec, _) in &b.flags {
        flags.insert(spec.id.to_string(), true);
    }
    let mut values: HashMap<String, Option<String>> = HashMap::new();
    for (spec, v) in &b.values {
        values.insert(spec.id.to_string(), v.clone());
    }
    for o in sub.opts {
        if !values.contains_key(o.id) {
            if let Some(env) = o.env {
                if let Ok(v) = std::env::var(env) {
                    if !v.is_empty() {
                        values.insert(o.id.to_string(), Some(v));
                    }
                }
            }
        }
        if !values.contains_key(o.id) {
            values.insert(o.id.to_string(), None);
        }
    }
    let mut positionals: HashMap<String, Vec<String>> = HashMap::new();
    positionals.insert("__pos".to_string(), b.positionals.clone());
    positionals.insert(sub.positionals.get(0).map(|p| p.id).unwrap_or("").to_string(), b.positionals.clone());

    Action::Run(sub.name, Matches { flags, values, positionals })
}
