//! Command line parsing.
//!
//! This re-implements the parts of `clap` 2.x that are observable through the
//! command line interface: the help output, the error messages and the
//! argument parsing quirks.

use std::collections::HashMap;

pub const VERSION: &str = "1.1.0";
pub const APP_NAME: &str = "bartib";
pub const AUTHOR: &str = "Nikolas Schmidt-Voigt <nikolas.schmidt-voigt@posteo.de>";
pub const ABOUT: &str = "A simple timetracker";
pub const TERM_WIDTH: usize = 120;

#[derive(Clone, Copy, PartialEq)]
pub enum ArgKind {
    Flag,
    Opt,
}

pub struct ArgSpec {
    pub id: &'static str,
    pub short: Option<char>,
    pub long: Option<&'static str>,
    pub kind: ArgKind,
    pub val_name: &'static str,
    pub help: &'static str,
    pub env: Option<&'static str>,
    pub default: Option<&'static str>,
}

impl ArgSpec {
    /// The string used for computing the width of the help column.
    fn spec(&self) -> String {
        let mut s = match self.long {
            Some(l) => format!("--{}", l),
            None => format!("-{}", self.short.unwrap()),
        };
        if self.kind == ArgKind::Opt {
            s.push_str(&format!(" <{}>", self.val_name));
        }
        s
    }

    /// The rendered argument (without the leading TAB).
    fn rendered(&self) -> String {
        let mut s = String::new();
        match (self.short, self.long) {
            (Some(c), Some(l)) => {
                s.push('-');
                s.push(c);
                s.push_str(", --");
                s.push_str(l);
            }
            (Some(c), None) => {
                s.push('-');
                s.push(c);
            }
            (None, Some(l)) => {
                s.push_str("    --");
                s.push_str(l);
            }
            (None, None) => {}
        }
        if self.kind == ArgKind::Opt {
            s.push_str(&format!(" <{}>", self.val_name));
        }
        s
    }

    /// How the argument is written inside a usage line.
    fn usage_repr(&self) -> String {
        match self.long {
            Some(l) => {
                if self.kind == ArgKind::Opt {
                    format!("--{} <{}>", l, self.val_name)
                } else {
                    format!("--{}", l)
                }
            }
            None => {
                if self.kind == ArgKind::Opt {
                    format!("-{} <{}>", self.short.unwrap(), self.val_name)
                } else {
                    format!("-{}", self.short.unwrap())
                }
            }
        }
    }
}

pub struct PositionalSpec {
    pub id: &'static str,
    pub name: &'static str,
    pub many: bool,
    pub help: &'static str,
    pub default: Option<&'static str>,
}

impl PositionalSpec {
    fn spec(&self) -> String {
        if self.many {
            format!("<{}>...", self.name)
        } else {
            format!("<{}>", self.name)
        }
    }
}

pub struct SubDef {
    pub name: &'static str,
    pub about: &'static str,
    pub usage_suffix: &'static str,
    pub flags: &'static [ArgSpec],
    pub opts: &'static [ArgSpec],
    pub positionals: &'static [PositionalSpec],
}

