pub const LIST_FLAGS: &[ArgSpec] = &[
    flag("current_week", None, Some("current_week"), "show activities of the current week"),
    flag("help", Some('h'), Some("help"), "Prints help information"),
    flag("last_week", None, Some("last_week"), "show activities of the last week"),
    flag("no_grouping", None, Some("no_grouping"), "do not group activities by date in list"),
    flag("today", None, Some("today"), "show activities of the current day"),
    flag("yesterday", None, Some("yesterday"), "show yesterdays' activities"),
