pub const LIST_OPTS: &[ArgSpec] = &[
    opt("date", Some('d'), Some("date"), "DATE", "show activities of a certain date only"),
    opt("from", None, Some("from"), "FROM_DATE", "begin of date range (inclusive)"),
    opt("number", Some('n'), Some("number"), "NUMBER", "maximum number of activities to display"),
    opt("project", Some('p'), Some("project"), "PROJECT", "do list activities for this project only"),
    opt("round", None, Some("round"), "round", "rounds the start and end time to the nearest duration. Durations can be in minutes or hours. E.g. 15m or 4h"),
    opt("to", None, Some("to"), "TO_DATE", "end of date range (inclusive)"),
