// ---------------------------------------------------------------------------
// help rendering
// ---------------------------------------------------------------------------

fn pad_to(s: &str, width: usize) -> String {
    let mut out = s.to_string();
    let len = s.chars().count();
    for _ in len..width {
        out.push(' ');
    }
    out
}

/// Greedy word wrapping, breaking on spaces.
fn wrap(text: &str, avail: usize) -> Vec<String> {
    let mut lines = Vec::new();
    let mut cur = String::new();
    for word in text.split(' ') {
        if cur.is_empty() {
            cur.push_str(word);
        } else if cur.chars().count() + 1 + word.chars().count() <= avail {
            cur.push(' ');
            cur.push_str(word);
        } else {
            lines.push(std::mem::take(&mut cur));
            cur.push_str(word);
        }
    }
    if !cur.is_empty() || lines.is_empty() {
        lines.push(cur);
    }
    lines
}

fn write_arg_line(out: &mut String, spec: &str, col: usize, help: &str) {
    out.push_str(&pad_to(spec, col));
    let avail = TERM_WIDTH.saturating_sub(col + 4);
    if col + help.chars().count() + 4 >= TERM_WIDTH {
        let lines = wrap(help, avail);
        for (i, l) in lines.iter().enumerate() {
            if i > 0 {
                out.push('\n');
                out.push_str(&" ".repeat(col));
            }
            out.push_str(l);
        }
    } else {
        out.push_str(help);
    }
    out.push('\n');
}

pub fn top_usage(bin: &str) -> String {
    format!("{} [OPTIONS] <SUBCOMMAND>", bin)
}

pub fn sub_usage(bin: &str, sub: &SubDef) -> String {
    if sub.usage_suffix.is_empty() {
        format!("{} {}", bin, sub.name)
    } else {
        format!("{} {} {}", bin, sub.name, sub.usage_suffix)
    }
}

pub fn render_top_help(bin: &str) -> String {
    let mut out = String::new();
    out.push_str(&format!("{} {}\n", APP_NAME, VERSION));
    out.push_str(AUTHOR);
    out.push('\n');
    out.push_str(ABOUT);
    out.push_str("\n\nUSAGE:\n    ");
    out.push_str(&top_usage(bin));
    out.push_str("\n\nFLAGS:\n");
    let flags = [
        flag("help", Some('h'), Some("help"), "Prints help information"),
        flag("version", Some('V'), Some("version"), "Prints version information"),
    ];
    let longest = flags.iter().map(|f| f.spec().chars().count()).max().unwrap_or(2);
    let col = longest + 12;
    for f in flags.iter() {
        write_arg_line(&mut out, &format!("{}{}", TAB, f.rendered()), col, f.help);
    }
    out.push_str("\nOPTIONS:\n");
    let file_env = std::env::var("BARTIB_FILE").unwrap_or_default();
    let f = ArgSpec {
        id: "file",
        short: Some('f'),
        long: None,
        kind: ArgKind::Opt,
        val_name: "FILE",
        help: "the file in which bartib tracks all the activities",
        env: Some("BARTIB_FILE"),
        default: None,
    };
    let longest = f.spec().chars().count();
    let col = longest + 12;
    let mut help = f.help.to_string();
    help.push_str(&format!(" [env: {}={}]", "BARTIB_FILE", file_env));
    write_arg_line(&mut out, &format!("{}{}", TAB, f.rendered()), col, &help);
    out.push_str("\nSUBCOMMANDS:\n");
    let subs = subcommands();
    let longest = subs.iter().map(|s| s.name.chars().count()).max().unwrap_or(2);
    let col = longest + 8;
    for s in &subs {
        write_arg_line(&mut out, &format!("{}{}", TAB, s.name), col, s.about);
    }
    out.push_str("\nTo get help for a specific subcommand, run `bartib [SUBCOMMAND] --help`.\n");
    out.push_str("To get started, view the `start` help with `bartib start --help`\n");
    out
}

pub fn render_sub_help(bin: &str, sub: &SubDef) -> String {
    let mut out = String::new();
    out.push_str(&format!("{}-{} \n", bin, sub.name));
    out.push_str(sub.about);
    out.push_str("\n\nUSAGE:\n    ");
    out.push_str(&sub_usage(bin, sub));
    out.push('\n');
    if !sub.flags.is_empty() {
        out.push_str("\nFLAGS:\n");
        let longest = sub.flags.iter().map(|f| f.spec().chars().count()).max().unwrap_or(2);
        let col = longest + 12;
        for f in sub.flags {
            write_arg_line(&mut out, &format!("{}{}", TAB, f.rendered()), col, f.help);
        }
    }
    if !sub.opts.is_empty() {
        out.push_str("\nOPTIONS:\n");
        let longest = sub.opts.iter().map(|o| o.spec().chars().count()).max().unwrap_or(2);
        let col = longest + 12;
        for o in sub.opts {
            let mut help = o.help.to_string();
            if let Some(env) = o.env {
                let val = std::env::var(env).unwrap_or_default();
                help.push_str(&format!(" [env: {}={}]", env, val));
            }
            if let Some(d) = o.default {
                help.push_str(&format!(" [default: {}]", d));
            }
            write_arg_line(&mut out, &format!("{}{}", TAB, o.rendered()), col, &help);
        }
    }
    if !sub.positionals.is_empty() {
        out.push_str("\nARGS:\n");
        let longest = sub.positionals.iter().map(|p| p.spec().chars().count()).max().unwrap_or(2);
        let col = longest + 8;
        for p in sub.positionals {
            let mut help = p.help.to_string();
            if let Some(d) = p.default {
                help.push_str(&format!(" [default: {}]", d));
            }
            write_arg_line(&mut out, &format!("{}{}", TAB, p.spec()), col, &help);
        }
    }
    out
}

// ---------------------------------------------------------------------------
// parsing
// ---------------------------------------------------------------------------

pub enum Action {
    /// print to stdout, exit 0
    Print(String),
    /// print to stderr, exit 1
    Fail(String),
    /// print to stderr, exit 1  (help text for a missing subcommand)
    FailHelp(String),
    Version,
    Run(&'static str, Matches),
}

pub struct Matches {
    flags: HashMap<String, bool>,
    values: HashMap<String, Option<String>>,
    positionals: Vec<String>,
}

impl Matches {
    pub fn flag(&self, id: &str) -> bool {
        *self.flags.get(id).unwrap_or(&false)
    }
    pub fn value(&self, id: &str) -> Option<&str> {
        self.values.get(id).and_then(|v| v.as_deref())
    }
    pub fn positional(&self, id: &str) -> Option<&str> {
        self.positionals.first().map(|s| s.as_str())
    }
    pub fn positionals(&self) -> &[String] {
        &self.positionals
    }
}

pub struct Parsed<'a> {
    pub bin: &'a str,
    pub sub: &'a SubDef,
    /// (spec, value, index of appearance)
    entries: Vec<(&'static ArgSpec, Option<String>, usize)>,
    positionals: Vec<String>,
    pos_index: HashMap<String, usize>,
}

impl<'a> Parsed<'a> {
    fn seen(&self, id: &str) -> bool {
        self.entries.iter().any(|(s, _, _)| s.id == id)
    }
    fn value_of(&self, id: &str) -> Option<&Option<String>> {
        self.entries.iter().find(|(s, _, _)| s.id == id).map(|(_, v, _)| v)
    }
    fn order_of(&self, id: &str) -> usize {
        self.entries
            .iter()
            .find(|(s, _, _)| s.id == id)
            .map(|(_, _, i)| *i)
            .unwrap_or(usize::MAX)
    }
}

/// Mutually exclusive argument groups (date selection flags of list/report).
fn conflicts_of(id: &str) -> Vec<&'static str> {
    match id {
        "from" => vec!["date", "today", "yesterday", "current_week", "last_week"],
        "to" => vec!["date", "today", "yesterday", "current_week", "last_week"],
        "date" => vec!["today", "yesterday", "current_week", "last_week"],
        "today" => vec!["date", "yesterday", "current_week", "last_week"],
        "yesterday" => vec!["current_week", "last_week"],
        "current_week" => vec!["last_week"],
        "last_week" => vec![],
        _ => vec![],
    }
}

fn conflict_priority(id: &str) -> usize {
    match id {
        "from" => 6,
        "to" => 5,
        "date" => 4,
        "today" => 3,
        "yesterday" => 2,
        "current_week" => 1,
        "last_week" => 0,
        _ => 100,
    }
}

struct UsageBuilder<'a> {
    bin: &'a str,
    sub: &'a SubDef,
    entries: Vec<(&'static ArgSpec, usize)>,
}

impl<'a> UsageBuilder<'a> {
    /// usage line using the arguments that are visible (non required, non
    /// positional).  Falls back to the full usage line when nothing is present.
    fn smart_usage(&self) -> String {
        let mut used: Vec<&ArgSpec> = Vec::new();
        for (spec, _) in &self.entries {
            if !self.is_required(spec.id) {
                used.push(spec);
            }
        }
        if used.is_empty() {
            return sub_usage(self.bin, self.sub);
        }
        for o in self.sub.opts {
            if self.is_required(o.id) && !used.iter().any(|s| s.id == o.id) {
                used.push(o);
            }
        }
        let mut reprs: Vec<String> = used.iter().map(|s| s.usage_repr()).collect();
        reprs.sort();
        format!("{} {} {}", self.bin, self.sub.name, reprs.join(" "))
    }

    fn is_required(&self, id: &str) -> bool {
        self.sub.name == "start" && (id == "description" || id == "project")
    }
}

fn err_unknown(ub: &UsageBuilder, arg: &str) -> Action {
    Action::Fail(format!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
        arg,
        ub.smart_usage()
    ))
}

fn err_empty_value(ub: &UsageBuilder, spec: &ArgSpec) -> Action {
    Action::Fail(format!(
        "error: The argument '{}' requires a value but none was supplied\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
        spec.usage_repr(),
        ub.smart_usage()
    ))
}

fn err_multiple(ub: &UsageBuilder, spec: &ArgSpec) -> Action {
    Action::Fail(format!(
        "error: The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
        spec.usage_repr(),
        ub.smart_usage()
    ))
}

fn err_conflict(ub: &UsageBuilder, a: &ArgSpec, b: &ArgSpec) -> Action {
    Action::Fail(format!(
        "error: The argument '{}' cannot be used with '{}'\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
        a.usage_repr(),
        b.usage_repr(),
        ub.smart_usage()
    ))
}

fn find_spec(sub: &SubDef, id: &str) -> &'static ArgSpec {
    sub.flags
        .iter()
        .chain(sub.opts.iter())
        .find(|d| d.id == id)
        .unwrap()
}

fn find_by_long(sub: &SubDef, long: &str) -> Option<&'static ArgSpec> {
    sub.opts.iter().chain(sub.flags.iter()).find(|d| d.long == Some(long))
}

fn find_by_short(sub: &SubDef, short: char) -> Option<&'static ArgSpec> {
    sub.opts.iter().chain(sub.flags.iter()).find(|d| d.short == Some(short))
}

pub fn parse_sub(bin: &str, sub: &SubDef, args: &[String]) -> Action {
    let mut entries: Vec<(&'static ArgSpec, Option<String>, usize)> = Vec::new();
    let mut positionals: Vec<String> = Vec::new();
    let mut idx = 0usize;
    let mut only_positionals = false;

    let mut i = 0;
    while i < args.len() {
        let arg = args[i].clone();
        i += 1;
        if only_positionals {
            positionals.push(arg);
            idx += 1;
            continue;
        }
        if arg == "--" {
            only_positionals = true;
            continue;
        }
        if arg.starts_with("--") {
            let body = &arg[2..];
            let (name, inline_val) = match body.find('=') {
                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                None => (body, None),
            };
            let spec = match find_by_long(sub, name) {
                Some(s) => s,
                None => {
                    let ub = UsageBuilder { bin, sub, entries: entries.iter().map(|(s, _, i)| (*s, *i)).collect() };
                    return err_unknown(&ub, &format!("--{}", name));
                }
            };
            if sub.name == "help" {
                // the help subcommand accepts anything
                positionals.push(arg);
                idx += 1;
                continue;
            }
            if spec.kind == ArgKind::Flag {
                entries.push((spec, None, idx));
                idx += 1;
            } else {
                match inline_val {
                    Some(v) => {
                        entries.push((spec, Some(v), idx));
                        idx += 1;
                    }
                    None => {
                        if i < args.len() && !args[i].starts_with('-') {
                            entries.push((spec, Some(args[i].clone()), idx));
                            i += 1;
                            idx += 1;
                        } else {
                            entries.push((spec, None, idx));
                            idx += 1;
                        }
                    }
                }
            }
        } else if arg.starts_with('-') && arg.chars().count() > 1 {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut ci = 0;
            while ci < chars.len() {
                let c = chars[ci];
                ci += 1;
                let spec = match find_by_short(sub, c) {
                    Some(s) => s,
                    None => {
                        let ub = UsageBuilder { bin, sub, entries: entries.iter().map(|(s, _, i)| (*s, *i)).collect() };
                        return err_unknown(&ub, &format!("-{}", c));
                    }
                };
                if sub.name == "help" {
                    positionals.push(format!("-{}", c));
                    idx += 1;
                    continue;
                }
                if spec.kind == ArgKind::Flag {
                    entries.push((spec, None, idx));
                    idx += 1;
                } else {
                    let rest: String = chars[ci..].iter().collect();
                    ci = chars.len();
                    if !rest.is_empty() {
                        let val = match rest.strip_prefix('=') {
                            Some(st) => st.to_string(),
                            None => rest,
                        };
                        entries.push((spec, Some(val), idx));
                        idx += 1;
                    } else if i < args.len() && !args[i].starts_with('-') {
                        entries.push((spec, Some(args[i].clone()), idx));
                        i += 1;
                        idx += 1;
                    } else {
                        entries.push((spec, None, idx));
                        idx += 1;
                    }
                }
            }
        } else {
            // positional
            if sub.name == "help" {
                positionals.push(arg);
                idx += 1;
                continue;
            }
            let many = sub.positionals.iter().any(|p| p.many);
            let max = if many { usize::MAX } else { sub.positionals.len() };
            if sub.positionals.is_empty() || positionals.len() >= max {
                let ub = UsageBuilder { bin, sub, entries: entries.iter().map(|(s, _, i)| (*s, *i)).collect() };
                return err_unknown(&ub, &arg);
            }
            positionals.push(arg);
            idx += 1;
        }
    }

    let ub = UsageBuilder { bin, sub, entries: entries.iter().map(|(s, _, i)| (*s, *i)).collect() };

    // 1. missing required arguments
    if sub.name == "start" {
        let missing: Vec<&ArgSpec> = sub
            .opts
            .iter()
            .filter(|o| o.id == "description" || o.id == "project")
            .filter(|o| !entries.iter().any(|(s, _, _)| s.id == o.id))
            .collect();
        if !missing.is_empty() {
            let mut list = String::new();
            for m in &missing {
                list.push_str(&format!("    {}\n", m.usage_repr()));
            }
            return Action::Fail(format!(
                "error: The following required arguments were not provided:\n{}\nUSAGE:\n    {}\n\nFor more information try --help\n",
                list,
                sub_usage(bin, sub)
            ));
        }
    }

    // 2. empty value (last processed argument was an option without a value)
    if let Some((spec, val, ord)) = entries.iter().rev().find(|(s, _, _)| s.kind == ArgKind::Opt) {
        let _ = ord;
        if val.is_none() {
            return err_empty_value(&ub, spec);
        }
    }

    // 3. conflicts
    let present: Vec<&'static ArgSpec> = entries.iter().map(|(s, _, _)| *s).collect();
    let mut conflicting: Vec<&'static ArgSpec> = present
        .iter()
        .cloned()
        .filter(|s| !conflicts_of(s.id).is_empty())
        .collect();
    if !conflicting.is_empty() {
        conflicting.sort_by_key(|s| std::cmp::Reverse(conflict_priority(s.id)));
        let a = conflicting[0];
        let partners: Vec<&'static ArgSpec> = conflicts_of(a.id)
            .into_iter()
            .filter_map(|p| present.iter().find(|s| s.id == p))
            .collect();
        if let Some(b) = partners.iter().max_by_key(|p| ub_order(&entries, p.id)).copied() {
            return err_conflict(&ub, a, b);
        }
    }

    // 4. duplicates
    for s in present.iter() {
        let count = present.iter().filter(|x| x.id == s.id).count();
        if count > 1 {
            return err_multiple(&ub, s);
        }
    }

    // build matches
    let mut flags: HashMap<String, bool> = HashMap::new();
    let mut values: HashMap<String, Option<String>> = HashMap::new();
    for (spec, v, _) in &entries {
        match spec.kind {
            ArgKind::Flag => {
                flags.insert(spec.id.to_string(), true);
            }
            ArgKind::Opt => {
                values.insert(spec.id.to_string(), v.clone());
            }
        }
    }
    for o in sub.opts {
        if !values.contains_key(o.id) {
            values.insert(o.id.to_string(), None);
        }
    }
    for p in sub.positionals {
        if let Some(d) = p.default {
            if positionals.is_empty() {
                positionals.push(d.to_string());
            }
        }
    }
    if sub.name == "help" && positionals.is_empty() {
        // no args -> top level help
    }

    Action::Run(
        sub.name,
        Matches { flags, values, positionals },
    )
}

fn ub_order(entries: &[(&'static ArgSpec, Option<String>, usize)], id: &str) -> usize {
    entries
        .iter()
        .filter(|(s, _, _)| s.id == id)
        .map(|(_, _, i)| *i)
        .next()
        .unwrap_or(usize::MAX)
}

pub fn parse_top(bin: &str, args: &[String]) -> Action {
    let mut file: Option<String> = None;
    let mut idx = 0usize;
    let mut i = 0;
    while i < args.len() {
        let arg = args[i].clone();
        i += 1;
        if arg == "--" {
            break;
        }
        if arg.starts_with("--") {
            let body = &arg[2..];
            let (name, inline_val) = match body.find('=') {
                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                None => (body, None),
            };
            match name {
                "help" => return Action::Print(render_top_help(bin)),
                "version" => return Action::Version,
                _ => {
                    let usage = if file.is_some() {
                        format!("{} -f <FILE>", bin)
                    } else {
                        top_usage(bin)
                    };
                    return Action::Fail(format!(
                        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
                        format!("--{}", name),
                        usage
                    ));
                }
            }
        } else if arg.starts_with('-') && arg.chars().count() > 1 {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut ci = 0;
            while ci < chars.len() {
                let c = chars[ci];
                ci += 1;
                match c {
                    'h' => return Action::Print(render_top_help(bin)),
                    'V' => return Action::Version,
                    'f' => {
                        let rest: String = chars[ci..].iter().collect();
                        ci = chars.len();
                        let val = if rest.is_empty() {
                            if i < args.len() && !args[i].starts_with('-') {
                                let v = args[i].clone();
                                i += 1;
                                Some(v)
                            } else {
                                None
                            }
                        } else {
                            match rest.strip_prefix('=') {
                                Some(st) => Some(st.to_string()),
                                None => Some(rest),
                            }
                        };
                        if let Some(v) = val {
                            if file.is_some() {
                                return Action::Fail(format!(
                                    "error: The argument '-f <FILE>' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {} -f <FILE>\n\nFor more information try --help\n",
                                    bin
                                ));
                            }
                            file = Some(v);
                        }
                        idx += 1;
                    }
                    _ => {
                        let usage = if file.is_some() { format!("{} -f <FILE>", bin) } else { top_usage(bin) };
                        return Action::Fail(format!(
                            "error: Found argument '-{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
                            c, usage
                        ));
                    }
                }
            }
        } else {
            // potential subcommand
            let subs = subcommands();
            match subs.iter().find(|s| s.name == arg) {
                Some(sub) => {
                    let rest = &args[i..];
                    return match parse_sub(bin, sub, rest) {
                        Action::Run(n, m) => Action::Run(n, m),
                        Action::Print(s) => Action::Print(s),
                        Action::Fail(s) => Action::Fail(s),
                        Action::FailHelp(s) => Action::FailHelp(s),
                        Action::Version => Action::Version,
                    };
                }
                None => {
                    let usage = if file.is_some() { format!("{} -f <FILE>", bin) } else { top_usage(bin) };
                    return Action::Fail(format!(
                        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
                        arg, usage
                    ));
                }
            }
        }
    }
    let _ = idx;
    // no subcommand -> help on stderr, exit code 1
    Action::FailHelp(render_top_help(bin))
}
RSEOF
echo ok; wc -l /workspace/src/cli.rs"}

