//! The activity log file.

use crate::datetime::{self, NaiveDateTime, ParseErrorKind};
use std::io::Write;
use std::path::Path;

#[derive(Debug, Clone)]
pub struct Activity {
    pub start: NaiveDateTime,
    pub end: Option<NaiveDateTime>,
    pub description: String,
    pub project: String,
    pub line: usize,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum LogError {
    /// the line does not have the expected shape
    Activity,
    /// a timestamp could not be parsed
    DateTime,
}

impl LogError {
    pub fn message(&self) -> &'static str {
        match self {
            LogError::Activity => "could not parse activity",
            LogError::DateTime => "could not parse date or time of activity",
        }
    }
}

pub struct LogFile {
    pub activities: Vec<Activity>,
    pub errors: Vec<(usize, String, LogError)>,
    /// the raw lines as read from the file
    pub lines: Vec<String>,
}

fn parse_timestamp(s: &str) -> Result<(NaiveDateTime, bool), ParseErrorKind> {
    match datetime::parse_datetime_second(s) {
        Ok(dt) => Ok((dt, true)),
        Err(_) => datetime::parse_datetime_minute(s).map(|dt| (dt, false)),
    }
}

/// Parses a single log line.
pub fn parse_line(line: &str, line_no: usize) -> Result<Activity, LogError> {
    let (time_part, rest) = match line.split_once('|') {
        Some(p) => p,
        None => return Err(LogError::Activity),
    };
    if rest.is_empty() {
        return Err(LogError::Activity);
    }
    let (project_part, description_part) = match rest.split_once('|') {
        Some((p, d)) => (p, Some(d)),
        None => (rest, None),
    };
    let project = project_part.trim().to_string();
    let description = description_part.map(|d| d.trim().to_string()).unwrap_or_default();

    let time_part = time_part.trim();
    let mut it = time_part.split(" - ");
    let start_str = it.next().unwrap_or("");
    let end_str = it.next();

    let (start, secs) = match parse_timestamp(start_str) {
        Ok(v) => v,
        Err(_) => return Err(LogError::DateTime),
    };
    if secs {
        crate::render::precision_warning();
    }
    let start = crate::render::normalize(start);

    let end = match end_str {
        Some(e) => {
            let (end, esecs) = match parse_timestamp(e) {
                Ok(v) => v,
                Err(_) => return Err(LogError::DateTime),
            };
            if esecs {
                crate::render::precision_warning();
            }
            let end = crate::render::normalize(end);
            Some(end)
        }
        None => None,
    };

    Ok(Activity {
        start,
        end,
        description,
        project,
        line: line_no,
    })
}

impl Activity {
    /// Renders the activity in the canonical log file format.
    pub fn to_line(&self) -> String {
        let mut s = String::new();
        s.push_str(&self.start.format_full());
        if let Some(e) = &self.end {
            s.push_str(" - ");
            s.push_str(&e.format_full());
        }
        s.push_str(" | ");
        s.push_str(&self.project);
        s.push_str(" | ");
        s.push_str(&self.description);
        s
    }

    pub fn is_running(&self) -> bool {
        self.end.is_none()
    }

    /// Duration in whole minutes (rounded, as the tool only knows minutes).
    pub fn duration_minutes(&self) -> i64 {
        match &self.end {
            Some(e) => self.start.diff_minutes(e),
            None => {
                let now = datetime::now_datetime();
                self.start.diff_minutes(&now)
            }
        }
    }
}

pub fn read_file(path: &str) -> Result<LogFile, String> {
    let data = std::fs::read_to_string(Path::new(path))
        .map_err(|e| format!("Could not read from file: {}\n\nCaused by:\n    {}\n", path, e))?;
    Ok(parse_content(&data))
}

pub fn parse_content(data: &str) -> LogFile {
    let mut activities = Vec::new();
    let mut errors = Vec::new();
    let mut lines = Vec::new();
    let mut reader = data.as_bytes();
    // mimic BufReader::lines() with map_while(Result::ok): reading stops at the
    // first line that is not valid utf-8
    let mut pos = 0usize;
    let text = String::from_utf_lossy(data.as_bytes());
    let _ = reader;
    let mut line_no = 0usize;
    let mut stopped = false;
    for raw in text.split_inclusive('\n') {
        pos += raw.len();
        let mut l = raw.trim_end_matches('\n').to_string();
        if l.ends_with('\r') {
            l.pop();
        }
        line_no += 1;
        match parse_line(&l, line_no) {
            Ok(a) => activities.push(a),
            Err(e) => errors.push((line_no, l.clone(), e)),
        }
        lines.push(l);
        if pos < data.len() && !data.is_char_boundary(pos) {
            stopped = true;
            break;
        }
    }
    let _ = stopped;
    LogFile {
        activities,
        errors,
        lines,
    }
}

/// Writes the given lines to the file.
pub fn write_lines(path: &str, lines: &[String]) -> Result<(), String> {
    let mut data = String::new();
    for l in lines {
        data.push_str(l);
        data.push('\n');
    }
    let mut f = std::fs::File::create(Path::new(path)).map_err(|e| e.to_string())?;
    f.write_all(data.as_bytes()).map_err(|e| e.to_string())?;
    Ok(())
}

/// Appends a single line, creating the file if needed.
pub fn append_line(path: &str, line: &str) -> Result<(), String> {
    let mut data = String::new();
    if let Ok(existing) = std::fs::read_to_string(Path::new(path)) {
        data.push_str(&existing);
        if !data.ends_with('\n') && !data.is_empty() {
            data.push('\n');
        }
    }
    data.push_str(line);
    data.push('\n');
