}

pub fn yellow(s: &str) -> String {
    format!("\u{1b}[33m{}\u{1b}[0m", s)
}

/// Formats a duration in minutes the way bartib does.
pub fn fmt_duration(minutes: i64) -> String {
    if minutes < 1 {
        String::from("<1m")
    } else if minutes < 60 {
        format!("{:02}m", minutes)
    } else {
        format!("{}h {:02}m", minutes / 60, minutes % 60)
    }
}

/// Parses the `--round` argument.
pub fn parse_round(s: &str) -> Option<Option<i64>> {
    if s.is_empty() {
        // slice index panic in the original implementation
        panic!("byte index 18446744073709551615 is out of bounds of ``");
    }
    let (num_str, unit) = s.split_at(s.len() - 1);
    match unit {
        "m" => match num_str.parse::<i64>() {
            Ok(n) => Some(Some(n * 60)),
            Err(_) => None,
        },
        "h" => match num_str.parse::<i64>() {
            Ok(n) => Some(Some(n * 3600)),
            Err(_) => None,
        },
        _ => match num_str.parse::<i64>() {
            Ok(_) => Err_unit(),
            Err(_) => None,
        },
    }
}

fn Err_unit() -> Option<Option<i64>> {
    ErrUnit
}

const ErrUnit: Option<Option<i64>> = None;

/// Rounds a timestamp (given as seconds since the epoch) to the nearest
/// multiple of `round_secs`.
pub fn round_secs(total: i64, round_secs: i64) -> i64 {
    let n = (total as f64 / round_secs as f64).round();
    round_secs * (n as i64)
}
