//! Implementation of the bartib sub commands.

use crate::activity::{self, Activity, LogError, LogFile};
use crate::cli::{Matches, SubDef};
use crate::datetime::{self, NaiveDate, NaiveDateTime};
use crate::render;
use std::process::Command;

// ---------------------------------------------------------------------------
// shared helpers
// ---------------------------------------------------------------------------

fn anyhow_err(msg: &str) -> String {
    format!("Error: {}\n", msg)
}

fn anyhow_caused(msg: &str, cause: &str) -> String {
    format!("Error: {}\n\nCaused by:\n    {}\n", msg, cause)
}

fn resolve_file(top: Option<&str>) -> Result<String, String> {
    if let Some(f) = top {
        return Ok(f.to_string());
    }
    if let Ok(f) = std::env::var("BARTIB_FILE") {
        return Ok(f);
    }
    Err(anyhow_err(
        "Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable",
    ))
}

fn load(file: &str) -> Result<LogFile, String> {
    activity::read_file(file).map_err(|m| anyhow_caused(&m[8..m.find("\n\n").map(|i| i + 2).unwrap_or(m.len())], &m[m.find("\n    ").map(|i| i + 4).unwrap_or(0)..].trim_end_matches('\n')))
}

fn load_or(file: &str) -> Result<LogFile, String> {
    if !std::path::Path::new(file).exists() {
        return Ok(LogFile { activities: vec![], errors: vec![], lines: vec![] });
    }
    load(file)
}

fn parse_number(s: &str) -> Option<u64> {
    match s.parse::<u64>() {
        Ok(n) => Some(n),
        Err(_) => {
            println!(
                "Can not parse \"{}\" as number. Argument for -n/--number is ignored",
                s
            );
            None
        }
    }
}

fn parse_date_opt(s: &str, opt: &str) -> Option<NaiveDate> {
    match datetime::parse_date(s) {
        Ok(d) => Some(d),
        Err(e) => {
            println!(
                "Can not parse \"{}\" as date. Argument for {} is ignored ({})",
                s,
                opt,
                e.message()
            );
            None
        }
    }
}

fn parse_time_opt(s: &str) -> Option<NaiveDateTime> {
    match datetime::parse_time(s) {
        Ok(t) => {
            let now = datetime::now_datetime();
            Some(NaiveDateTime {
                date: now.date,
                secs: t.secs,
            })
        }
        Err(e) => {
            println!(
                "Can not parse \"{}\" as time. Argument for -t/--time is ignored ({})",
                s,
                e.message()
            );
            None
        }
    }
}

fn parse_round_opt(s: &str) -> Option<i64> {
    match render::parse_round(s) {
        render::Round::Value(v) => Some(v),
        render::Round::Warn => {
            println!(
                "Can not parse \"{}\" as duration. Argument for --round is ignored",
                s
            );
            None
        }
        render::Round::Silent => None,
    }
}

fn apply_round(a: &mut Activity, round_secs: i64) {
    let total = a.start.total_secs();
    a.start = NaiveDateTime::from_total_secs(render::round_secs(total, round_secs));
    if let Some(e) = a.end {
        let t = e.total_secs();
        a.end = Some(NaiveDateTime::from_total_secs(render::round_secs(t, round_secs)));
    }
}

/// Sorts activities by their start time, ascending and stable.
fn sort_by_start(acts: &mut [Activity]) {
    acts.sort_by(|a, b| a.start.cmp(&b.start));
}

/// Activities sorted by start time descending, deduplicated by
/// (description, project).
fn distinct_recent(acts: &[Activity]) -> Vec<Activity> {
    let mut sorted: Vec<&Activity> = acts.iter().collect();
    sorted.sort_by(|a, b| b.start.cmp(&a.start));
    let mut out: Vec<Activity> = Vec::new();
    for a in sorted {
        if !out
            .iter()
            .any(|x| x.description == a.description && x.project == a.project)
        {
            out.push(a.clone());
        }
    }
    out
}

// ---------------------------------------------------------------------------
// table rendering
// ---------------------------------------------------------------------------

struct Cell {
    text: String,
}

fn row_line(cells: &[String], colored: Option<&str>) -> String {
    let mut out = String::new();
    for (i, c) in cells.iter().enumerate() {
        if i > 0 {
            out.push(' ');
        }
        match colored {
            Some(code) => out.push_str(&format!("\u{1b}[{}m{}\u{1b}[0m", code, c)),
            None => out.push_str(c),
        }
    }
    out.push(' ');
    out
}

fn header_line(titles: &[String], widths: &[usize]) -> String {
    let cells: Vec<String> = titles
        .iter()
        .zip(widths.iter())
        .map(|(t, w)| render::underline(&render::pad_nbsp(t, *w)))
        .collect();
    row_line(&cells, None)
}

// ---------------------------------------------------------------------------
// commands
// ---------------------------------------------------------------------------

pub fn run(bin: &str, sub: &SubDef, top_file: Option<&str>, m: &Matches) -> Result<(), String> {
    match sub.name {
        "cancel" => cancel(top_file),
        "change" => change(top_file, m),
        "check" => check(top_file),
        "continue" => continue_cmd(top_file, m),
        "current" => current(top_file),
        "edit" => edit(top_file, m),
        "help" => help_cmd(bin, m),
        "last" => last(top_file, m),
        "list" => list(top_file, m),
        "projects" => projects(top_file, m),
        "report" => report(top_file, m),
        "sanity" => sanity(top_file),
        "search" => search(top_file, m),
        "start" => start(top_file, m),
        "status" => status(top_file, m),
        "stop" => stop(top_file, m),
        _ => Ok(()),
    }
}

// -- check ------------------------------------------------------------------

pub fn check(top_file: Option<&str>) -> Result<(), String> {
    let file = resolve_file(top_file)?;
    let log = load(&file)?;
    if log.errors.is_empty() {
        println!("All lines in the file have been successfully parsed as activities.");
        return Ok(());
    }
    println!(
        "Found {} line(s) with parsing errors",
        log.errors.len()
    );
    println!();
    for (n, line, err) in &log.errors {
        println!("{}", line);
        println!("  -> {} (Line: {})", err.message(), n);
        println!();
    }
    Ok(())
}

// -- sanity -----------------------------------------------------------------

pub fn sanity(top_file: Option<&str>) -> Result<(), String> {
    let file = resolve_file(top_file)?;
    let log = load(&file)?;
    activity::read_warning(&log.errors);
    let mut acts = log.activities.clone();
    sort_by_start(&mut acts);
    let mut found = false;
    for (i, a) in acts.iter().enumerate() {
        let mut msgs: Vec<&str> = Vec::new();
        if let Some(e) = &a.end {
            if e.total_secs() < a.start.total_secs() {
                msgs.push("Activity has negative duration");
            }
        }
        if acts[..i]
            .iter()
            .any(|p| p.end.map(|e| a.start.total_secs() < e.total_secs()).unwrap_or(false))
        {
            msgs.push("Activity started before another activity ended");
        }
        if msgs.is_empty() {
            continue;
        }
        found = true;
        for msg in msgs {
            println!("{}", msg);
        }
        println!(
            "{} (Started: {}, Ended: {}, Line: {})",
            a.description,
            a.start.format_full(),
            a.end
                .as_ref()
                .map(|e| e.format_full())
                .unwrap_or_else(|| "--".to_string()),
            a.line
        );
        println!();
    }
    if !found {
        println!("No unusual activities.");
    }
    Ok(())
}

// -- projects ---------------------------------------------------------------

pub fn projects(top_file: Option<&str>, m: &Matches) -> Result<(), String> {
    let file = resolve_file(top_file)?;
    let log = load(&file)?;
    activity::read_warning(&log.errors);
    let current = m.flag("current");
    let mut names: Vec<String> = Vec::new();
    for a in &log.activities {
        if current && !a.is_running() {
            continue;
        }
        if !names.iter().any(|n| n == &a.project) {
            names.push(a.project.clone());
        }
    }
    names.sort();
    for n in names {
        if m.flag("no-quotes") {
            println!("{}", n);
        } else {
            println!("\"{}\"", n);
        }
    }
    Ok(())
}

// -- last -------------------------------------------------------------------

pub fn last(top_file: Option<&str>, m: &Matches) -> Result<(), String> {
    let file = resolve_file(top_file)?;
    let log = load(&file)?;
    activity::read_warning(&log.errors);
    let number = m
        .value("number")
        .and_then(|s| parse_number(s))
        .unwrap_or(10) as usize;
    let all = distinct_recent(&log.activities);
    if all.is_empty() {
        println!("No activities have been tracked yet");
        return Ok(());
    }
    let shown: Vec<Activity> = all.into_iter().take(number).collect();
    if shown.is_empty() {
        println!("No activities have been tracked yet");
        return Ok(());
    }
    let num_width = shown.iter().map(|a| format!("[{}]", 0).len()).max().unwrap_or(3);
    let _ = num_width;
    let idx_width = format!("[{}]", shown.len() - 1).chars().count();
    let desc_width = shown
        .iter()
        .map(|a| a.description.chars().count())
        .chain(std::iter::once("Description".chars().count()))
        .max()
        .unwrap();
    let proj_width = shown
        .iter()
        .map(|a| a.project.chars().count())
        .chain(std::iter::once("Project".chars().count()))
        .max()
        .unwrap();
    println!();
    let num_cell = render::pad_nbsp(" #", idx_width);
    let cells = vec![
        render::underline(&num_cell),
        render::underline(&render::pad_nbsp("Description", desc_width)),
        render::underline(&render::pad_nbsp("Project", proj_width)),
    ];
    println!("{}", row_line(&cells, None));
    for (i, a) in shown.iter().enumerate() {
        let cells = vec![
            render::pad_nbsp(&format!("[{}]", i), idx_width),
            render::pad_nbsp(&a.description, desc_width),
            render::pad_nbsp(&a.project, proj_width),
        ];
        println!("{}", row_line(&cells, None));
    }
    println!();
    Ok(())
}

// -- search -----------------------------------------------------------------

pub fn search(top_file: Option<&str>, m: &Matches) -> Result<(), String> {
    let file = resolve_file(top_file)?;
    let log = load(&file)?;
    activity::read_warning(&log.errors);
    let term = m.positional("SEARCH_TERM").unwrap_or("").to_lowercase();
    let all = distinct_recent(&log.activities);
    let shown: Vec<(usize, &Activity)> = all
        .iter()
        .enumerate()
        .filter(|(_, a)| {
            a.description.to_lowercase().contains(&term) || a.project.to_lowercase().contains(&term)
        })
        .map(|(i, a)| (i, a))
        .collect();
    if shown.is_empty() {
        println!("No matching activities found");
        return Ok(());
    }
    let idx_width = format!("[{}]", all.len() - 1).chars().count();
    let desc_width = shown
        .iter()
        .map(|(_, a)| a.description.chars().count())
        .chain(std::iter::once("Description".chars().count()))
        .max()
        .unwrap();
    let proj_width = shown
        .iter()
        .map(|(_, a)| a.project.chars().count())
        .chain(std::iter::once("Project".chars().count()))
        .max()
        .unwrap();
    println!();
    let num_cell = render::pad_nbsp(" #", idx_width);
    let cells = vec![
        render::underline(&num_cell),
        render::underline(&render::pad_nbsp("Description", desc_width)),
        render::underline(&render::pad_nbsp("Project", proj_width)),
    ];
    println!("{}", row_line(&cells, None));
    for (i, a) in shown {
        let cells = vec![
            render::pad_nbsp(&format!("[{}]", i), idx_width),
            render::pad_nbsp(&a.description, desc_width),
            render::pad_nbsp(&a.project, proj_width),
        ];
        println!("{}", row_line(&cells, None));
    }
    println!();
    Ok(())
}

// -- current ----------------------------------------------------------------

pub fn current(top_file: Option<&str>) -> Result<(), String> {
    let file = resolve_file(top_file)?;
    let log = load(&file)?;
    activity::read_warning(&log.errors);
    let running: Vec<&Activity> = log.activities.iter().filter(|a| a.is_running()).collect();
    if running.is_empty() {
        println!("No Activity is currently running");
        return Ok(());
    }
    let started: Vec<String> = running.iter().map(|a| a.start.format_full()).collect();
    let started_width = started
        .iter()
        .map(|s| s.chars().count())
        .chain(std::iter::once("Started At".chars().count()))
        .max()
        .unwrap();
    let desc_width = running
        .iter()
        .map(|a| a.description.chars().count())
        .chain(std::iter::once("Description".chars().count()))
        .max()
        .unwrap();
    let proj_width = running
        .iter()
        .map(|a| a.project.chars().count())
        .chain(std::iter::once("Project".chars().count()))
        .max()
        .unwrap();
    let dur_width = running
        .iter()
        .map(|a| render::fmt_duration(a.duration_minutes()).chars().count())
        .chain(std::iter::once("Duration".chars().count()))
        .max()
        .unwrap();
    println!();
    let cells = vec![
        render::underline(&render::pad_space("Started At", started_width)),
        render::underline(&render::pad_space("Description", desc_width)),
        render::underline(&render::pad_space("Project", proj_width)),
        render::underline(&render::pad_space("Duration", dur_width)),
    ];
    println!("{}", row_line(&cells, None));
    for a in running {
        let cells = vec![
            render::pad_space(&a.start.format_full(), started_width),
            render::pad_space(&a.description, desc_width),
            render::pad_space(&a.project, proj_width),
            render::pad_space(&render::fmt_duration(a.duration_minutes()), dur_width),
        ];
        println!("{}", row_line(&cells, None));
    }
    println!();
    Ok(())
}
RSEOF
echo ok"}

