fn anyhow_err(msg: &str) -> String {
    format!("Error: {}\n", msg)
}

fn anyhow_caused(msg: &str, cause: &str) -> String {
    format!("Error: {}\n\nCaused by:\n    {}\n", msg, cause)
}

fn resolve_file(top: Option<&str>) -> Result<String, String> {
    if let Some(f) = top {
        return Ok(f.to_string());
    }
    if let Ok(f) = std::env::var("BARTIB_FILE") {
