fn load(file: &str) -> Result<LogFile, String> {
    activity::read_file(file).map_err(|m| anyhow_caused(&m[8..m.find("\n\n").map(|i| i + 2).unwrap_or(m.len())], &m[m.find("\n    ").map(|i| i + 4).unwrap_or(0)..].trim_end_matches('\n')))
}

fn load_or(file: &str) -> Result<LogFile, String> {
