fn parse_date_opt(s: &str, opt: &str) -> Option<NaiveDate> {
    match datetime::parse_date(s) {
        Ok(d) => Some(d),
        Err(e) => {
            println!(
                "Can not parse \"{}\" as date. Argument for {} is ignored ({})",
                s,
                opt,
                e.message()
            );
            None
        }
    }
}

fn parse_time_opt(s: &str) -> Option<NaiveDateTime> {
    match datetime::parse_time(s) {
        Ok(t) => {
            let now = datetime::now_datetime();
            Some(NaiveDateTime {
                date: now.date,
                secs: t.secs,
            })
        }
        Err(e) => {
            println!(
                "Can not parse \"{}\" as time. Argument for -t/--time is ignored ({})",
