fn dot_pad(s: &str, width: usize) -> String {
    let mut out = String::from(s);
    let len = s.chars().count();
    for _ in len..width {
        out.push('.');
    }
    out
}

pub fn report(top_file: Option<&str>, m: &Matches) -> Result<(), String> {
    let file = resolve_file(top_file)?;
    let log = load(&file)?;
    activity::read_warning(&log.errors);
    let mut acts = log.activities.clone();

    if let Some(r) = m.value("round").and_then(parse_round_opt) {
        for a in acts.iter_mut() {
            apply_round(a, r);
        }
    }

    let project = m.value("project").map(|s| s.to_string());
    if let Some(p) = &project {
        acts.retain(|a| &a.project == p);
    }

    let sels: Vec<DateSel> = {
        let mut v = Vec::new();
        if let Some(d) = m.value("date").and_then(|s| parse_date_opt(s, "-d/--date")) {
            v.push(DateSel::Date(d));
        }
        if let Some(d) = m.value("from").and_then(|s| parse_date_opt(s, "--from")) {
            v.push(DateSel::From(d));
        }
        if let Some(d) = m.value("to").and_then(|s| parse_date_opt(s, "--to")) {
            v.push(DateSel::To(d));
        }
        if m.flag("today") {
            v.push(DateSel::Today);
        }
        if m.flag("yesterday") {
            v.push(DateSel::Yesterday);
        }
        if m.flag("current_week") {
            v.push(DateSel::CurrentWeek);
        }
        if m.flag("last_week") {
            v.push(DateSel::LastWeek);
        }
        v
    };
    for s in &sels {
        acts.retain(|a| activity_in_range(a, s));
    }

    // group by (project, description)
    let mut groups: Vec<(String, String, i64)> = Vec::new();
    for a in &acts {
        let d = a.duration_minutes();
        match groups
            .iter_mut()
            .find(|(p, de, _)| p == &a.project && de == &a.description)
        {
            Some((_, _, t)) => *t += d,
            None => groups.push((a.project.clone(), a.description.clone(), d)),
        }
    }
    // sort by project then description
    groups.sort_by(|a, b| (&a.0, &a.1).cmp(&(&b.0, &b.1)));

    let max_desc = groups.iter().map(|(_, d, _)| d.chars().count()).max().unwrap_or(0);
    let max_proj = groups.iter().map(|(p, _, _)| p.chars().count()).max().unwrap_or(0);
    let content_width = std::cmp::max(std::cmp::max(4 + max_desc, max_proj), 5);
    let dur_width = groups
        .iter()
        .map(|(_, _, t)| render::fmt_duration(*t).chars().count())
        .chain(std::iter::once(render::fmt_duration(0).chars().count()))
        .max()
        .unwrap();
    let total: i64 = groups.iter().map(|(_, _, t)| *t).sum();
    let dur_width = std::cmp::max(dur_width, render::fmt_duration(total).chars().count());

    println!();
    for (p, d, t) in &groups {
        println!(
            "{}",
            render::bold(&format!(
                "{} {}",
                dot_pad(p, content_width),
                format!("{:>width$}", render::fmt_duration(*t), width = dur_width)
            ))
        );
        println!(
            "    {} {:>width$}",
            dot_pad(d, content_width - 4),
            render::fmt_duration(*t),
            width = dur_width
        );
        println!();
    }
    println!(
        "{}",
        render::bold(&format!(
            "{} {}",
            dot_pad("Total", content_width),
            format!("{:>width$}", render::fmt_duration(total), width = dur_width)
        ))
    );
    println!();
    println!();
    Ok(())
}
