#[derive(Clone, Copy, PartialEq)]
enum DateSel {
    Date(NaiveDate),
    Today,
    Yesterday,
    CurrentWeek,
    LastWeek,
    From(NaiveDate),
    To(NaiveDate),
}

fn week_start(d: NaiveDate) -> NaiveDate {
    d.first_day_of_week()
}

fn activity_in_range(a: &Activity, sel: &DateSel) -> bool {
    match sel {
        DateSel::Date(d) => a.start.date == *d,
        DateSel::Today => a.start.date == datetime::now_datetime().date,
        DateSel::Yesterday => a.start.date == datetime::now_datetime().date.pred_days(1),
        DateSel::CurrentWeek => {
            let ws = week_start(datetime::now_datetime().date);
            a.start.date >= ws && a.start.date < ws.succ_days(7)
        }
        DateSel::LastWeek => {
            let ws = week_start(datetime::now_datetime().date).pred_days(7);
            a.start.date >= ws && a.start.date < ws.succ_days(7)
        }
        DateSel::From(d) => a.start.date >= *d,
        DateSel::To(d) => a.start.date <= *d,
    }
