// ---------------------------------------------------------------------------
// file modification helpers
// ---------------------------------------------------------------------------

fn rewrite_file(
    file: &str,
    log: &LogFile,
    activities: &[Activity],
    skip: &[usize],
) -> Result<(), String> {
    let mut out: Vec<String> = Vec::new();
    for (i, line) in log.lines.iter().enumerate() {
        let n = i + 1;
        if skip.contains(&n) {
            out.push(line.clone());
            continue;
        }
        match activities.iter().find(|a| a.line == n) {
            Some(a) => out.push(a.to_line()),
            None => out.push(line.clone()),
        }
    }
    activity::write_lines(file, &out)
}

fn stop_running(acts: &mut Vec<Activity>, at: NaiveDateTime) -> Vec<usize> {
    let mut messages = Vec::new();
    for a in acts.iter_mut() {
        if a.is_running() {
            let dur = a.start.diff_minutes(&at);
            messages.push(format!(
                "Stopped activity: \"{}\" ({}) started at {} ({})",
                a.description,
                a.project,
                a.start.format_full(),
                render::fmt_duration(dur)
            ));
            a.end = Some(at);
        }
    }
    messages
