// -- start ------------------------------------------------------------------

pub fn start(top_file: Option<&str>, m: &Matches) -> Result<(), String> {
    let file = resolve_file(top_file)?;
    let at = match time_arg(m) {
        Some(t) => t,
        None => datetime::now_datetime(),
    };
    let log = load_or(&file)?;
    let mut acts = log.activities.clone();
    let now = datetime::now_datetime();
    let msgs = stop_running(&mut acts, now);
    for msg in &msgs {
        println!("{}", msg);
    }
    let description = m.value("description").unwrap_or("").to_string();
    let project = m.value("project").unwrap_or("").to_string();
    let new = Activity {
        start: at,
        end: None,
        description: description.clone(),
        project: project.clone(),
        line: log.lines.len() + 1,
    };
    println!(
        "Started activity: \"{}\" ({}) at {}",
        description,
        project,
        at.format_full()
    );
    let mut out: Vec<String> = Vec::new();
    for (i, line) in log.lines.iter().enumerate() {
        let n = i + 1;
        match acts.iter().find(|a| a.line == n) {
            Some(a) => out.push(a.to_line()),
            None => out.push(line.clone()),
        }
    }
    out.push(new.to_line());
    activity::write_lines(&file, &out)?;
    Ok(())
}

// -- stop -------------------------------------------------------------------

pub fn stop(top_file: Option<&str>, m: &Matches) -> Result<(), String> {
    let file = resolve_file(top_file)?;
    let log = load(&file)?;
    let mut acts = log.activities.clone();
    let at = time_arg(m).unwrap_or_else(datetime::now_datetime);
    let msgs = stop_running(&mut acts, at);
    for msg in &msgs {
        println!("{}", msg);
    }
    rewrite_file(&file, &log, &acts, &[])?;
    Ok(())
}

// -- cancel -----------------------------------------------------------------

pub fn cancel(top_file: Option<&str>) -> Result<(), String> {
    let file = resolve_file(top_file)?;
    let log = load(&file)?;
    let mut acts = log.activities.clone();
    let mut skip: Vec<usize> = Vec::new();
    for a in acts.iter() {
        if a.is_running() {
            println!(
                "Canceled activity: \"{}\" ({}) started at {}",
                a.description,
                a.project,
                a.start.format_full()
            );
            skip.push(a.line);
        }
    }
    let kept: Vec<Activity> = acts
        .into_iter()
        .filter(|a| !skip.contains(&a.line))
        .collect();
    rewrite_file(&file, &log, &kept, &[])?;
    Ok(())
}

// -- change -----------------------------------------------------------------

pub fn change(top_file: Option<&str>, m: &Matches) -> Result<(), String> {
    let file = resolve_file(top_file)?;
    let log = load(&file)?;
    let mut acts = log.activities.clone();
    let description = m.value("description");
    let project = m.value("project");
    let time = time_arg(m);
    if description.is_none() && project.is_none() && time.is_none() {
        return Ok(());
    }
    for a in acts.iter_mut() {
        if a.is_running() {
            if let Some(d) = description {
                a.description = d.to_string();
            }
            if let Some(p) = project {
                a.project = p.to_string();
            }
            if let Some(t) = time {
                a.start = t;
            }
            println!(
                "Changed activity: \"{}\" ({}) started at {}",
                a.description,
                a.project,
                a.start.format_full()
            );
        }
    }
    rewrite_file(&file, &log, &acts, &[])?;
    Ok(())
}

// -- continue ---------------------------------------------------------------

pub fn continue_cmd(top_file: Option<&str>, m: &Matches) -> Result<(), String> {
    let file = resolve_file(top_file)?;
    let log = load(&file)?;
    let number = match m.value("NUMBER") {
        Some(s) => parse_number(s).unwrap_or(0),
        None => 0,
    } as usize;
    let distinct = distinct_recent(&log.activities);
    if distinct.is_empty() {
        return Err(anyhow_err("No activity has been started before."));
    }
    if number >= distinct.len() {
        return Err(anyhow_err(&format!(
            "Less than {} distinct activities have been logged yet",
            number
        )));
    }
    let target = &distinct[number];
    let description = m
        .value("description")
        .map(|s| s.to_string())
        .unwrap_or_else(|| target.description.clone());
    let project = m
        .value("project")
        .map(|s| s.to_string())
        .unwrap_or_else(|| target.project.clone());
    let at = match time_arg(m) {
        Some(t) => t,
        None => datetime::now_datetime(),
    };
    let mut acts = log.activities.clone();
    let now = datetime::now_datetime();
    let msgs = stop_running(&mut acts, now);
    for msg in &msgs {
        println!("{}", msg);
    }
    println!(
        "Started activity: \"{}\" ({}) at {}",
        description,
        project,
        at.format_full()
    );
    let mut out: Vec<String> = Vec::new();
    for (i, line) in log.lines.iter().enumerate() {
        let n = i + 1;
        match acts.iter().find(|a| a.line == n) {
            Some(a) => out.push(a.to_line()),
            None => out.push(line.clone()),
        }
    }
    out.push(
        Activity {
            start: at,
            end: None,
            description,
            project,
            line: log.lines.len() + 1,
        }
        .to_line(),
    );
    activity::write_lines(&file, &out)?;
    Ok(())
}

// -- edit -------------------------------------------------------------------

pub fn edit(top_file: Option<&str>, m: &Matches) -> Result<(), String> {
    let file = resolve_file(top_file)?;
    let editor = match m.value("editor") {
        Some(e) => e.to_string(),
        None => match std::env::var("EDITOR") {
            Ok(e) => e,
            Err(_) => return Err(anyhow_err("editor command is missing")),
        },
    };
    match Command::new(&editor).arg(&file).spawn() {
        Ok(mut child) => {
            let _ = child.wait();
            Ok(())
        }
        Err(e) => Err(anyhow_caused("", &e.to_string()).replace("Error: \n\n", "Error: ")),
    }
}

// -- help -------------------------------------------------------------------

pub fn help_cmd(bin: &str, m: &Matches) -> Result<(), String> {
    let subs = crate::cli::subcommands();
    let args = m.positionals();
    let mut current: Option<&SubDef> = None;
    for a in args {
        match subs.iter().find(|s| s.name == a) {
            Some(s) => {
                current = Some(s);
            }
            None => {
                return Err(format!(
                    "error: The subcommand '{}' wasn't recognized\n\nUSAGE:\n\t{} help <subcommands>...\n\nFor more information try --help\n",
                    a, bin
                ));
            }
        }
    }
    match current {
        Some(s) => {
            print!("{}", crate::cli::render_sub_help(bin, s));
            Ok(())
        }
        None => {
            print!("{}", crate::cli::render_top_help(bin));
            Ok(())
        }
    }
}

// -- status -----------------------------------------------------------------

fn label_line(label: &str, dur: &str) -> String {
    format!(
        "\u{1b}[3m \u{1b}[0m\u{1b}[2;3m {} \u{1b}[0m\u{1b}[1m{}\u{1b}[0m\u{1b}[3m\n\u{1b}[0m",
        render::dot_pad(label, 30),
        dur
    )
}

pub fn status(top_file: Option<&str>, m: &Matches) -> Result<(), String> {
    let file = resolve_file(top_file)?;
    let log = load(&file)?;
    activity::read_warning(&log.errors);
    let acts = log.activities.clone();
    let filter = m.value("project").map(|s| s.to_string());
    let mut selected: Vec<&Activity> = acts
        .iter()
        .filter(|a| filter.as_ref().map(|p| &a.project == p).unwrap_or(true))
        .collect();

    let mut out = String::new();
    out.push_str("\u{1b}[2m\n =======");
    match &filter {
        Some(p) => {
            out.push_str(&format!(
                "\u{1b}[0m\u{1b}[3m Status for project: \u{1b}[0m\u{1b}[1m{}\u{1b}[0m",
                p
            ));
        }
        None => {
            out.push_str("\u{1b}[0m\u{1b}[3m Status for \u{1b}[0m\u{1b}[1mALL\u{1b}[0m\u{1b}[3m projects \u{1b}[0m");
        }
    }
    out.push_str("\u{1b}[2m ======= \n");

    out.push_str("\u{1b}[0m\u{1b}[2;3m\n  NOW: \u{1b}[0m");
    let running: Vec<&&Activity> = selected.iter().filter(|a| a.is_running()).collect();
    if let Some(a) = running.first() {
        let now = datetime::now_datetime();
        let dur = a.start.diff_minutes(&now);
        out.push_str(&format!(
            "\u{1b}[1;32m{}\u{1b}[0m\u{1b}[2;3m on \u{1b}[0m\u{1b}[3m{}\u{1b}[0m\u{1b}[2m ...... \u{1b}[0m\u{1b}[1m{}\u{1b}[0m\u{1b}[2m\n\n\u{1b}[0m",
            a.description,
            a.project,
            render::fmt_duration(dur)
        ));
    } else {
        out.push_str("\u{1b}[1m NO Activity\n\n\u{1b}[0m");
    }

    let now = datetime::now_datetime();
    let today = now.date;
    let week_start = today.first_day_of_week();
    let month_start = today.first_day_of_month();
    let in_month = |d: NaiveDate| d >= month_start && d < month_start.succ_days_in_month();
    let in_week = |d: NaiveDate| d >= week_start && d < week_start.succ_days(7);

    let sum = |pred: &dyn Fn(&Activity) -> bool| -> i64 {
        selected
            .iter()
            .filter(|a| pred(a))
            .map(|a| a.duration_minutes())
            .sum()
    };
    let today_sum = sum(&|a: &Activity| a.start.date == today);
    let week_sum = sum(&|a: &Activity| in_week(a.start.date));
    let month_sum = sum(&|a: &Activity| in_month(a.start.date));

    out.push_str(&label_line("Today", &render::fmt_duration(today_sum)));
    out.push_str(&label_line("Current week", &render::fmt_duration(week_sum)));
    out.push_str(&label_line("Current month", &render::fmt_duration(month_sum)));
    out.push('\n');
    print!("{}", out);
    Ok(())
}
