    let file = resolve_file(top_file)?;
    let log = load(&file)?;
    activity::read_warning(&log.errors);
    let number = m
        .value("number")
        .and_then(|s| parse_number(s))
        .unwrap_or(10) as usize;
    let all = distinct_recent(&log.activities);
    if all.is_empty() {
        println!("No activities have been tracked yet");
        return Ok(());
    }
