    let shown: Vec<Activity> = all[offset..].to_vec();
    if shown.is_empty() {
        println!("No activities have been tracked yet");
        return Ok(());
    }
    render_numbered(&shown, shown.len() - 1)?;
    Ok(())
}

/// Prints the numbered two column table used by `last` and `search`.
/// `max_index` is the highest index that is displayed.
fn render_numbered(shown: &[Activity], max_index: usize) -> Result<(), String> {
    let idx_width = format!("[{}]", max_index).chars().count();
    let desc_width = shown
        .iter()
        .map(|a| a.description.chars().count())
        .chain(std::iter::once("Description".chars().count()))
        .max()
        .unwrap();
    let proj_width = shown
        .iter()
        .map(|a| a.project.chars().count())
        .chain(std::iter::once("Project".chars().count()))
        .max()
        .unwrap();
    println!();
    let num_cell = render::pad_nbsp(" #", idx_width);
