new = '''    // group by project
    let mut projects: Vec<String> = Vec::new();
    for a in &acts {
        if !projects.iter().any(|p| p == &a.project) {
            projects.push(a.project.clone());
        }
    }
    projects.sort();
    let mut groups: Vec<(String, Vec<(String, i64)>)> = Vec::new();
    for p in &projects {
        let mut descs: Vec<(String, i64)> = Vec::new();
        for a in acts.iter().filter(|a| &a.project == p) {
            let d = a.duration_minutes();
            match descs.iter_mut().find(|(de, _)| de == &a.description) {
                Some((_, t)) => *t += d,
                None => descs.push((a.description.clone(), d)),
            }
        }
        descs.sort_by(|a, b| a.0.cmp(&b.0));
        groups.push((p.clone(), descs));
    }

    let max_desc = groups
        .iter()
        .flat_map(|(_, ds)| ds.iter().map(|(d, _)| d.chars().count()))
        .max()
        .unwrap_or(0);
    let max_proj = groups.iter().map(|(p, _)| p.chars().count()).max().unwrap_or(0);
    let content_width = std::cmp::max(std::cmp::max(4 + max_desc, max_proj), 5);
    let total: i64 = groups
        .iter()
        .flat_map(|(_, ds)| ds.iter().map(|(_, t)| *t))
        .sum();
    let dur_width = groups
        .iter()
        .flat_map(|(_, ds)| ds.iter().map(|(_, t)| render::fmt_duration(*t).chars().count()))
        .chain(std::iter::once(render::fmt_duration(total).chars().count()))
        .max()
        .unwrap();

    println!();
    for (p, ds) in &groups {
        let ptotal: i64 = ds.iter().map(|(_, t)| *t).sum();
        println!(
            "{}",
            render::bold(&format!(
                "{} {}",
                render::dot_pad(p, content_width),
                format!("{:>width$}", render::fmt_duration(ptotal), width = dur_width)
            ))
        );
        for (d, t) in ds {
            println!(
                "    {} {:>width$}",
                render::dot_pad(d, content_width - 4),
                render::fmt_duration(*t),
                width = dur_width
            );
        }
        println!();
    }
    println!(
        "{}",
        render::bold(&format!(
            "{} {}",
            render::dot_pad("Total", content_width),
            format!("{:>width$}", render::fmt_duration(total), width = dur_width)
        ))
    );
    println!();
    Ok(())
}

